/* game_L28.js — Moonlight Mart, Lesson 28 (“let’s” in 반말: verb stem + -자: 하자, 먹자, 가자, 놀자; “let’s not”: -지 말자; more 반말 phrases:
   안녕, 잘 가, 잘 있어, 나, 너, 응/어, 아니/아니야).
   Who speaks how (from Lesson 27): Minji ↔ player 반말 (same age); Sua → player 존댓말, player → Sua 반말 (she gave permission); Mr. Kim and
   Grandma → player 반말, player → them 존댓말 (so to them “let’s” is the polite -아/어요 of Lesson 16); everybody else 존댓말.
   Lines: [castId, korean, english]. q.opts: correct option first (engine shuffles). odd: opts[0] is the WRONG sentence.
   Forms come from forms_L28.js (generated, checked against the book). Game words not in the book: 주전자 (kettle), 손전등 (flashlight),
   끓이다 (to boil, L10), 깨우다 (to wake someone), 모레 (the day after tomorrow), 벤치, 앉다 — glossed where they appear.
   App-written sentences are NOT yet checked by a native speaker (⚠ list in HANDOFF.md). lenient off at the end: 가자 / 가쟈. */

/* explains any wrong -자 / -지 말자 form w of verb d (used by textbook, workbook and the questions below; this file loads before them) */
MM.l28why = (d, w) => {
  const f = (MM.forms[28] || []).find(r => r.dict === d); if (!f) return '';
  const stem = d.slice(0, -1);
  if ((f.wrongJiMalja || []).includes(w) || /지 마자|지 않자|^안 | 안 /.test(w)) {
    if (/안 /.test(w)) return `“Let’s not” is not 안 + -자. Use 말다: ${f.jiMalja} (-지 말다 + -자).`;
    if (/지 마자/.test(w)) return `말다 keeps its ㄹ before -자: 말 + 자 = 말자 → ${f.jiMalja}. (마 is the casual order “don’t”: 하지 마.)`;
    if (/지 않자/.test(w)) return `-지 않다 is for statements (I don’t…). For “let’s not” the book uses 말다: ${f.jiMalja}.`;
    return `Let’s not = -지 말자: ${f.jiMalja}.`;
  }
  if (/자요$/.test(w)) return `-자 is 반말: no -요 after it. ${f.ja}. (The polite “let’s” is a different ending: ${f.hae}, Lesson 16.)`;
  if (w === f.hae.slice(0, -1) + '자') return `-자 goes straight onto the verb stem (${stem}), not onto the 해요 form: ${f.ja}.`;
  if (/으자$/.test(w)) return `No 으 before -자 (it begins with a consonant): ${f.ja}.`;
  if (f.irr === 'ㄹ') return `The ㄹ of the stem stays before -자: ${f.ja}.`;
  if (f.irr !== 'reg') return `-자 begins with a consonant, so the ${f.irr} irregular change does not happen: ${f.ja}.${f.irr === 'ㄷ' ? ` (${w} would be “let’s ${d === '걷다' ? 'hang / call' : 'lift'}”: ${d === '걷다' ? '걸다' : '들다'}.)` : ''}`;
  return `Verb stem + 자: ${f.ja}.`;
};

